REVOKE ALL ON FUNCTION test_private.namespace_key(text) FROM PUBLIC,anon,authenticated;
CREATE TEMP TABLE test_rebind_sources ON COMMIT DROP AS SELECT *,test_private.namespace_key(key) new_key FROM test_app_sync_private.sources WHERE key<>test_private.namespace_key(key);
INSERT INTO test_app_sync_private.sources(key,modules,client_enabled,dylan_only) SELECT new_key,modules,client_enabled,dylan_only FROM test_rebind_sources ON CONFLICT(key) DO NOTHING;
UPDATE public.test_app_dataset_revisions SET key=test_private.namespace_key(key) WHERE key<>test_private.namespace_key(key);
UPDATE test_app_sync_private.import_leases SET key=test_private.namespace_key(key) WHERE key<>test_private.namespace_key(key);
UPDATE test_app_sync_private.revision_broadcast_clock_v23163 SET key=test_private.namespace_key(key) WHERE key<>test_private.namespace_key(key);
UPDATE test_app_sync_private.import_runs SET source_keys=ARRAY(SELECT test_private.namespace_key(x) FROM unnest(source_keys) x),canonical_keys=ARRAY(SELECT test_private.namespace_key(x) FROM unnest(canonical_keys) x);
DELETE FROM test_app_sync_private.sources WHERE key IN(SELECT key FROM test_rebind_sources);
